import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, uniform, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const disposables = [];

  const imageUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const tex = ctx.textureLoader(imageUrl);
  if (tex) {
    tex.colorSpace = THREE.SRGBColorSpace;
  }

  const planeWidth = 3.2;
  const planeHeight = 2.0;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  disposables.push(geometry);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const grainStrength = uniform(0.03);
  const accentColor = uniform(new THREE.Color('#ff2a38'));
  const inkColor = uniform(new THREE.Color('#16161d'));

  const uvNode = uv();

  let colorNode;
  if (tex) {
    const texNode = texture(tex, uvNode);
    // subtle engineered gradient overlay from ink to accent based on vertical uv
    const gradient = mix(inkColor, accentColor, uvNode.y.mul(0.15));
    const grain = uvNode.x.mul(uvNode.y).fract().sub(0.5).mul(grainStrength);
    colorNode = vec4(
      texNode.rgb.mul(0.9).add(gradient.mul(0.1)).add(grain),
      texNode.a
    );
  } else {
    const gradient = mix(inkColor, accentColor, uvNode.y);
    colorNode = vec4(gradient, float(1.0));
  }

  material.colorNode = colorNode;
  disposables.push(material);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-title-plane';
  group.add(plane);

  // Text content: "Pricing" headline
  const textContent = config?.textContent?.[0]?.text || 'Pricing';
  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: textContent,
      font: 'Lora',
      weight: 400,
      size: 0.62 * 0.55, // headline scale, scaled down to fit plane
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      anchor: 'center',
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.02);
      group.add(textMesh);
      disposables.push(textMesh.geometry);
      if (textMesh.material) disposables.push(textMesh.material);
    }
  } catch (e) {
    // fail silently if font atlas unavailable, plane still renders
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') {
        d.dispose();
      }
    });
    while (group.children.length) {
      group.remove(group.children[0]);
    }
  };

  return group;
}
